       seen_count, valid_from, source_conversation_id, source_message_id, source_quote,
       extractor_version, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
  AND memory_type = #{memoryType}
  AND memory_key = #{memoryKey}
FOR UPDATE

SELECT id, user_id, memory_type, memory_key, content, importance, confidence, status,
       seen_count, valid_from, source_conversation_id, source_message_id, source_quote,
       extractor_version, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
  AND id = #{id}

SELECT id, user_id, memory_type, memory_key, content, importance, confidence, status,
       seen_count, valid_from, source_conversation_id, source_message_id, source_quote,
       extractor_version, expires_at, last_used_at, hit_count, created_at, updated_at
FROM ai_user_memory
WHERE user_id = #{userId}
  AND memory_type = #{memoryType}
  AND status IN ('ACTIVE', 'CANDIDATE')
  AND (expires_at IS NULL OR expires_at > now())
ORDER BY updated_at DESC
LIMIT #{limit}

